package com.voltsync.domain;

import java.util.*;

/**
 * Detailed diff output generated by an incremental re-plan.
 * Quantifies assignment perturbations and updated schedules.
 */
public record ReplanDiff(
        String planId,
        long baseVersion,
        long newVersion,
        int changedAssignmentsCount,
        Set<String> modifiedVehicles,
        Map<String, String> reassignedTrips,
        List<UnassignedTrip> newlyUnassignedTrips,
        List<ChargeEvent> newlyScheduledCharges,
        List<ChargeEvent> canceledCharges,
        long replanDurationMs
) {
    public ReplanDiff {
        modifiedVehicles = Collections.unmodifiableSet(new HashSet<>(modifiedVehicles));
        reassignedTrips = Collections.unmodifiableMap(new HashMap<>(reassignedTrips));
        newlyUnassignedTrips = Collections.unmodifiableList(new ArrayList<>(newlyUnassignedTrips));
        newlyScheduledCharges = Collections.unmodifiableList(new ArrayList<>(newlyScheduledCharges));
        canceledCharges = Collections.unmodifiableList(new ArrayList<>(canceledCharges));
    }

    public static ReplanDiff empty(String planId, long version, long durationMs) {
        return new ReplanDiff(
                planId, version, version, 0,
                Collections.emptySet(), Collections.emptyMap(),
                Collections.emptyList(), Collections.emptyList(), Collections.emptyList(),
                durationMs
        );
    }
}
